#!/usr/bin/env python3
"""Regenerates lib/data/companion_cutouts.dart and lib/data/companion_art.dart
from assets/companions/ without ImageMagick (needs Pillow). Same output as
scripts/gen_companion_art.sh for the cutouts; also lists the {id}_{c|r|e|l}
card images. Run after adding or editing art."""
import os
import re
import subprocess
from PIL import Image

root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
os.chdir(root)
art = 'assets/companions'
files = sorted(f for f in os.listdir(art) if f.endswith('.png'))

cut = [
    '// GENERATED by scripts/gen_companion_art.sh. Do not edit by hand.',
    '',
    "import 'dart:ui';",
    '',
    '/// Every bundled companion cutout: image size and the box around the',
    '/// creature (non-transparent pixels), both in image pixels.',
    'const Map<String, ({Size size, Rect body})> companionCutouts = {',
]
cards = [
    '// GENERATED by scripts/gen_companion_art.sh. Do not edit by hand.',
    '',
    "import 'dart:ui';",
    '',
    '/// Pixel size of every bundled companion image ({species}_{c|r|e|l}).',
    'const Map<String, Size> companionArt = {',
]
for f in files:
    id_ = f[:-4]
    im = Image.open(os.path.join(art, f))
    if re.fullmatch(r'[a-z]+(-rare|-epic|-legendary)?', id_):
        a = im.convert('RGBA').getchannel('A')
        x0, y0, x1, y1 = a.getbbox()
        cut.append(
            f"  '{id_}': (size: Size({im.width}, {im.height}), "
            f'body: Rect.fromLTWH({x0}, {y0}, {x1 - x0}, {y1 - y0})),'
        )
    elif re.fullmatch(r'[a-z]+_[crel]', id_):
        cards.append(f"  '{id_}': Size({im.width}, {im.height}),")
cut.append('};')
cards.append('};')
for path, lines in (
    ('lib/data/companion_cutouts.dart', cut),
    ('lib/data/companion_art.dart', cards),
):
    with open(path, 'w') as out:
        out.write('\n'.join(lines) + '\n')
    subprocess.run(['dart', 'format', path], check=True, capture_output=True)
